/**
 * Full category taxonomy for Pet Carrier: pet carriers only (see the
 * carrier-only note below for why Beds and Strollers aren't here).
 * Every node here becomes a real page at /[path], generated by
 * app/[section]/[[...path]]/page.tsx. Content (intro, why-choose, sizing
 * guide, FAQ) is generated from the `animal` and `descriptor` fields by
 * lib/category-content.ts, so adding a node here is enough to publish a
 * fully SEO-ready page, no per-category prose required.
 */

// Carrier-only as of 2026-09: Beds and Strollers were removed from the active
// site architecture (owner decision to keep pet-carrier.co.uk a focused
// carrier specialist rather than a general pet-products store; strollers
// never had any inventory and beds had only 6 products). See git history for
// the removed hub/sub/collection definitions if either is ever reintroduced,
// ideally as its own dedicated domain rather than back into this Section
// union, per the reasoning in that decision.
export type Section = "carriers";

export interface CategoryNode {
  path: string; // full URL path without leading slash, e.g. "carriers/dog-carriers/puppy-carriers"
  name: string; // display name / H1, e.g. "Puppy Carriers"
  section: Section;
  level: 1 | 2 | 3;
  parentPath: string | null;
  animal: string; // e.g. "dog", "cat", "rabbit", "multiple pets"
  descriptor: string; // who/what this category suits, used in generated copy
  kind: "hub" | "sub" | "collection";
}

function seg(parentPath: string, slug: string): string {
  return `${parentPath}/${slug}`;
}

function hub(
  section: Section,
  path: string,
  name: string,
  parentPath: string | null,
  level: 1 | 2 | 3,
  animal: string,
  descriptor: string
): CategoryNode {
  return { path, name, section, level, parentPath, animal, descriptor, kind: "hub" };
}

function sub(
  section: Section,
  parentPath: string,
  slug: string,
  name: string,
  level: 2 | 3,
  animal: string,
  descriptor: string
): CategoryNode {
  return {
    path: seg(parentPath, slug),
    name,
    section,
    level,
    parentPath,
    animal,
    descriptor,
    kind: "sub",
  };
}

function collection(
  section: Section,
  parentPath: string,
  slug: string,
  name: string,
  animal: string,
  descriptor: string
): CategoryNode {
  return {
    path: seg(parentPath, slug),
    name,
    section,
    level: 2,
    parentPath,
    animal,
    descriptor,
    kind: "collection",
  };
}

