export const SECTIONS: { value: Section; name: string }[] = [{ value: "carriers", name: "Carriers" }];

export function getCategoryByPath(path: string): CategoryNode | undefined {
  return CATEGORIES.find((c) => c.path === path);
}

export function getChildren(path: string): CategoryNode[] {
  return CATEGORIES.filter((c) => c.parentPath === path);
}

export function getBreadcrumbTrail(path: string): CategoryNode[] {
  const trail: CategoryNode[] = [];
  let current = getCategoryByPath(path);
  while (current) {
    trail.unshift(current);
    current = current.parentPath ? getCategoryByPath(current.parentPath) : undefined;
  }
  return trail;
}

export function getRelatedCategories(path: string, limit = 4): CategoryNode[] {
  const node = getCategoryByPath(path);
  if (!node) return [];

  if (node.parentPath) {
    const siblings = CATEGORIES.filter((c) => c.parentPath === node.parentPath && c.path !== path);
    if (siblings.length >= limit) return siblings.slice(0, limit);
    const parent = getCategoryByPath(node.parentPath);
    return parent ? [parent, ...siblings].slice(0, limit) : siblings.slice(0, limit);
  }

  return getChildren(path).slice(0, limit);
}

export function getSectionHub(section: Section): CategoryNode {
  const found = CATEGORIES.find((c) => c.path === section);
  if (!found) throw new Error(`No hub category found for section ${section}`);
  return found;
}
